build(a, snap) {
    const iv = a.iv.map((x) => x.slice()).sort((x, y) => x[0] - y[0] || x[1] - y[1]), res = [];
    const f = (x) => `[${x[0]}, ${x[1]}]`;
    const view = (i, touched) => [
      { t: "chips", label: "按起点排序后的区间", items: iv.map((x, j) => ({ v: f(x), cls: j === i ? "a" : j < i ? "d" : "" })) },
      { t: "chips", label: "结果", items: res.map((x, j) => ({ v: f(x), cls: touched && j === res.length - 1 ? "k" : "" })), empty: "还没有" },
    ];
    snap("排序", "先按起点排序。之后能合并的区间一定是挨着的。", view(-1));
    iv.forEach(([s, e], i) => {
      const last = res[res.length - 1];
      if (last && s <= last[1]) {
        const old = f(last); last[1] = Math.max(last[1], e);
        snap("合并", `${f([s, e])} 的起点 ${s} 不超过上一段 ${old} 的终点，两段<b>重叠</b>。终点取较大的，上一段变成 ${f(last)}。`, view(i, true));
      } else {
        res.push([s, e]);
        snap("另起一段", last ? `${f([s, e])} 的起点 ${s} 大于上一段的终点 ${last[1]}，不重叠，作为新的一段。` : `结果是空的，${f([s, e])} 直接放进去。`, view(i, true));
      }
    });
    snap("完成", `合并后剩下 <b>${res.length}</b> 段。`, view(iv.length), { kind: "ok", ans: res });
  }
